                    continue;
                if (项.min !== null && 深度 < 项.min)
                    continue;
                if (项.max !== null && 深度 > 项.max)
                    continue;
                try {
                    文本 = 文本.replace(项.re, 项.替换.replace(/\{\{match\}\}/gi, '$&'));
