                    if (s.主题模式)
                        主题模式.value = s.主题模式;
                    else
                        主题模式.value = localStorage.getItem(主题存储键) === '1' ? '夜间' : '日间'; // 旧键迁移
                    if (s.字号档)
                        字号档.value = s.字号档;
                    if (typeof s.正文字色 === 'string')
                        正文字色.value = s.正文字色;
                    if (typeof s.垫板浓度 === 'number')
                        垫板浓度.value = s.垫板浓度;
                    省流.value = !!s.省流;
                    减动效.value = !!s.减动效;
                    if (typeof s.立绘显示 === 'boolean')
                        立绘显示.value = s.立绘显示;
                    if (typeof s.二次变量结算 === 'boolean')
                        二次变量结算.value = s.二次变量结算;
                }
                else {
                    主题模式.value = localStorage.getItem(主题存储键) === '1' ? '夜间' : '日间';
